package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestReproIssueHandleContext(t *testing.T) {
	w := httptest.NewRecorder()
	ctx, engine := CreateTestContext(w)
	engine.GET("/hello/:name", func(c *Context) {
		c.String(http.StatusOK, "Hello %s", c.Param("name"))
	})
	var err error
	ctx.Request, err = http.NewRequest(http.MethodGet, "/hello/something", nil)
	if err != nil {
		t.Fatal(err)
	}
	engine.HandleContext(ctx)
	if w.Body.String() != "Hello something" {
		t.Fatalf("unexpected body: %q", w.Body.String())
	}
}
